{"packet_id":"D073-01","doc_id":"D073","jurisdiction":"San Diego, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"San Diego just cause for tenancy termination","requirement":"A landlord may not terminate a residential tenancy without just cause, which may be at-fault (rent default, nuisance, criminal activity, and similar) or no-fault (owner move-in, withdrawal from the rental market, government order, demolition, or substantial remodel).","key_value":"just cause required (at-fault or no-fault)","coverage_conditions":"Tenancies of more than 30 days in residential rental property in the city, subject to the exemptions of section 98.0703. Fixed-term leases of three months or less are not a tenancy.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"certificate_of_occupancy","min_units":null,"max_units":null,"owner_dependent":true,"other":"Housing issued a certificate of occupancy within the previous 15 years is exempt; owner-occupied single-family and two-unit properties are exempt"},"exemptions":"Transient and short-term occupancy; deed-restricted affordable housing; Mobilehome Residency Law mobilehomes; institutional, hospital and non-profit transitional housing; dormitories; owner-occupied single-family and two-unit properties; housing with a certificate of occupancy within 15 years; certain separately alienable properties.","penalty":null,"effective_date":"2023-06-24","citation":"San Diego Mun. Code § 98.0704","quoted_span":"A landlord shall not terminate a tenancy without just cause. For purposes of this Division, just cause includes at-fault just cause and no-fault just cause.","interaction":"Requires just cause consistent with California Civil Code section 1946.2; rights are in addition to state and federal law.","confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D073-01","doc_id":"D073","jurisdiction":"San Diego, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"San Diego residential tenant protections exemptions","requirement":"The Division does not apply to the listed residential rental property types and circumstances, which are exempt from its just cause and related tenant protections.","key_value":null,"coverage_conditions":"Exempts the listed property types and circumstances from the Division, including those with a certificate of occupancy within the previous 15 years.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"certificate_of_occupancy","min_units":null,"max_units":null,"owner_dependent":true,"other":"Owner-occupied single-family, two-unit and shared-facility properties exempt"},"exemptions":null,"penalty":null,"effective_date":"2023-06-24","citation":"San Diego Mun. Code § 98.0703","quoted_span":"This Division shall not apply to the following types of residential rental properties or residential circumstances:","interaction":null,"confidence":0.9,"conflict_flag":false,"conflict_note":null}
